(1, 1, 'styles.scss', 'frontend_sources_css', 'scss', '// Override Bootstrap\'s Sass default variables\r\n//\r\n// Nearly all variables in Bootstrap are written with the `!default` flag.\r\n// This allows you to override the default values of those variables before\r\n// you import Bootstrap\'s source Sass files.\r\n//\r\n// Overriding the default variable values is the best way to customize your\r\n// CSS without writing _new_ styles. For example, you can either change\r\n// `$body-color` or write more CSS that override\'s Bootstrap\'s CSS like so:\r\n// `body { color: red; }`.\r\n\r\n//\r\n// Bring in Bootstrap\r\n//\r\n\r\n// Option 1\r\n//\r\n// Import all of Bootstrap\'s CSS\r\n\r\n// @import \"bootstrap/scss/bootstrap\";\r\n\r\n// Option 2\r\n//\r\n// Place variable overrides first, then import just the styles you need. Note that some stylesheets are required no matter what.\r\n\r\n// Toggle global options\r\n$enable-gradients: true;\r\n$enable-shadows: true;\r\n$enable-cssgrid: true;\r\n\r\n$offcanvas-box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);\r\n\r\n// Include functions first\r\n@import \"bootstrap/scss/functions\";\r\n\r\n// Customize some defaults\r\n$body-color: #333;\r\n$body-bg: #fff;\r\n$border-radius: 0.4rem;\r\n$success: #7952b3;\r\n\r\n$tooltip-font-size: 12px;\r\n$tooltip-bg: var(--tooltip-background);\r\n$tooltip-color: var(--tooltip-text-color);\r\n$tooltip-opacity: 1;\r\n$tooltip-padding-y: 8px;\r\n$tooltip-padding-x: 12px;\r\n\r\n$container-max-widths: (\r\n  sm: 540px,\r\n  md: 720px,\r\n  lg: 960px,\r\n  xl: 1140px,\r\n  xxl: 1280px,\r\n);\r\n\r\n$nav-link-color: var(--text-secondary);\r\n$nav-link-hover-color: var(--text-teritiary);\r\n$nav-link-font-weight: 500;\r\n$nav-tabs-border-color: var(--border-color-default);\r\n$nav-tabs-link-active-color: var(--primary-colors-secondary);\r\n$nav-tabs-link-active-bg: transparent;\r\n$nav-tabs-link-active-border-color: transparent;\r\n$nav-tabs-link-hover-border-color: transparent;\r\n$nav-tabs-border-radius: 0;\r\n$nav-link-font-size: 14px;\r\n\r\n$modal-content-bg: var(--background-secondary);\r\n$modal-backdrop-bg: rgba(62, 50, 73, 0.65);\r\n$modal-backdrop-opacity: 1;\r\n$modal-content-border-width: 0;\r\n$modal-sm: 453px;\r\n$modal-md: 572px;\r\n$modal-dialog-margin-y-sm-up: 0;\r\n\r\n// Required\r\n@import \"bootstrap/scss/variables\";\r\n// @import \"bootstrap/scss/variables-dark\";\r\n@import \"bootstrap/scss/maps\";\r\n@import \"bootstrap/scss/mixins\";\r\n// @import \"bootstrap/scss/utilities\";\r\n@import \"bootstrap/scss/root\";\r\n@import \"bootstrap/scss/reboot\";\r\n\r\n// @import \"bootstrap/scss/type\";\r\n// @import \"bootstrap/scss/images\";\r\n@import \"bootstrap/scss/containers\";\r\n// @import \"bootstrap/scss/grid\";\r\n// @import \"bootstrap/scss/tables\";\r\n// @import \"bootstrap/scss/forms\";\r\n// @import \"bootstrap/scss/buttons\";\r\n@import \"bootstrap/scss/transitions\";\r\n// @import \"bootstrap/scss/dropdown\";\r\n// @import \"bootstrap/scss/button-group\";\r\n@import \"bootstrap/scss/nav\";\r\n// @import \"bootstrap/scss/navbar\"; // Requires nav\r\n// @import \"bootstrap/scss/card\";\r\n// @import \"bootstrap/scss/breadcrumb\";\r\n// @import \"bootstrap/scss/accordion\";\r\n// @import \"bootstrap/scss/pagination\";\r\n// @import \"bootstrap/scss/badge\";\r\n// @import \"bootstrap/scss/alert\";\r\n// @import \"bootstrap/scss/progress\";\r\n// @import \"bootstrap/scss/list-group\";\r\n// @import \"bootstrap/scss/close\";\r\n// @import \"bootstrap/scss/toasts\";\r\n@import \"bootstrap/scss/modal\"; // Requires transitions\r\n@import \"bootstrap/scss/tooltip\";\r\n// @import \"bootstrap/scss/popover\";\r\n// @import \"bootstrap/scss/carousel\";\r\n// @import \"bootstrap/scss/spinners\";\r\n// @import \"bootstrap/scss/offcanvas\"; // Requires transitions\r\n// @import \"bootstrap/scss/placeholders\";\r\n\r\n// Helpers\r\n// @import \"bootstrap/scss/helpers\";\r\n\r\n// Utilities\r\n// @import \"bootstrap/scss/utilities/api\";\r\n\r\n//\r\n// Custom styles\r\n//\r\n\r\n@import \"mixins\";\r\n\r\n@import \"property/colors\";\r\n@import \"property/display\";\r\n@import \"property/margin\";\r\n@import \"property/padding\";\r\n@import \"property/text\";\r\n@import \"property/position\";\r\n@import \"property/align-items\";\r\n@import \"property/justify-content\";\r\n@import \"property/object-fit\";\r\n@import \"property/transition\";\r\n@import \"property/gap\";\r\n@import \"property/transform\";\r\n@import \"property/rounded\";\r\n@import \"property/overflow\";\r\n@import \"property/cursor\";\r\n@import \"property/height\";\r\n@import \"property/width\";\r\n@import \"property/border\";\r\n@import \"property/z-index\";\r\n@import \"property/opacity\";\r\n\r\n@import \"colors\";\r\n@import \"fonts\";\r\n@import \"buttons\";\r\n@import \"link\";\r\n@import \"icons\";\r\n\r\n@import \"sets\";\r\n@import \"toast\";\r\n@import \"search\";\r\n@import \"categories\";\r\n@import \"skins\";\r\n@import \"user\";\r\n@import \"daily-reward\";\r\n@import \"info\";\r\n@import \"tasks\";\r\n@import \"social-network\";\r\n@import \"header\";\r\n@import \"footer\";\r\n@import \"menu\";\r\n@import \"stats\";\r\n@import \"banner\";\r\n@import \"menu-actions\";\r\n@import \"language\";\r\n@import \"inventory\";\r\n@import \"vape-block\";\r\n@import \"access-card\";\r\n@import \"pay\";\r\n@import \"_servers_navbar\";\r\n@import \"_kv-grid-table\";\r\n@import \"_pagination\";\r\n@import \"_form-group\";\r\n@import \"_select2\";\r\n@import \"_clockdown\";\r\n@import \"server_info\";\r\n\r\n@import \"page/servers\";\r\n@import \"page/rules\";\r\n@import \"page/buildings\";\r\n@import \"page/how-works\";\r\n@import \"page/support\";\r\n@import \"page/maps\";\r\n@import \"page/stats\";\r\n@import \"page/achievements\";\r\n@import \"page/referral\";\r\n@import \"page/blog\";\r\n@import \"page/custom-skins\";\r\n@import \"page/raid-table\";\r\n\r\n.user-select-none {\r\n  user-select: none;\r\n}\r\n\r\n.pe-none {\r\n  pointer-events: none;\r\n}\r\n\r\n.flex-wrap {\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.flex-column {\r\n  flex-direction: column;\r\n}\r\n\r\n.old-price {\r\n  @extend .line-through, .text-button-main-old-price-color-default;\r\n}\r\n\r\n.content-visibility-auto {\r\n  content-visibility: auto;\r\n}\r\n\r\n.nav {\r\n  &.nav-tabs {\r\n    @extend .gap-x-20;\r\n\r\n    & .nav-link {\r\n      @extend .p-0, .uppercase, .transition-border-color, .pb-4;\r\n      border: 0;\r\n      border-bottom: 3px solid transparent;\r\n\r\n      &.active {\r\n        border-bottom: 3px solid var(--primary-colors-secondary);\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n.main_title {\r\n  @extend h2, .mb-24;\r\n}\r\n\r\n.modal {\r\n  --bs-modal-margin: 1.75rem;\r\n  @media (max-width: 768px) {\r\n    background-color: var(--bs-modal-bg);\r\n  }\r\n  header {\r\n    @media (max-width: 768px) {\r\n      background: rgba(0, 0, 0, 0.4);\r\n      margin-bottom: 24px;\r\n    }\r\n  }\r\n  &.with-image {\r\n    .modal-dialog {\r\n      margin-top: 200px;\r\n      @media (max-width: 768px) {\r\n        margin: 0;\r\n        .modal-backdrop-image {\r\n          display: none;\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n.modal-dialog {\r\n  @extend .flex, .items-center;\r\n  //height: 100%;\r\n\r\n  @media (max-width: 768px) {\r\n    margin-left: 0;\r\n    margin-right: 0;\r\n    margin-top: 0;\r\n    max-width: 100%;\r\n  }\r\n  .modal-content {\r\n    border-radius: var(--block-radius);\r\n    position: relative;\r\n    overflow: hidden;\r\n    @media (max-width: 768px) {\r\n      border-radius: 0;\r\n    }\r\n  }\r\n\r\n  .modal-backdrop-image {\r\n    @include range(270, 270, \"px\");\r\n    @extend .absolute;\r\n    top: -200px;\r\n    left: 0;\r\n    right: 0;\r\n    margin-right: auto;\r\n    margin-left: auto;\r\n    z-index: 10;\r\n    display: none;\r\n\r\n    &_pay {\r\n      top: -193px;\r\n    }\r\n    &_promo {\r\n      top: -206px;\r\n    }\r\n    &.active {\r\n      display: block;\r\n    }\r\n  }\r\n}\r\n\r\n.short {\r\n  overflow: hidden;\r\n  white-space: nowrap;\r\n  text-overflow: ellipsis;\r\n}\r\n\r\n.main-content {\r\n  @extend .flex, .flex-column, .pt-32, .pl-0, .pr-0, .ml-0, .mr-0;\r\n  margin-right: auto;\r\n  margin-left: auto;\r\n  justify-items: center;\r\n  padding-bottom: 82px;\r\n  min-width: 100%;\r\n  transition:\r\n    max-width 0.25s ease-in-out,\r\n    min-width 0.25s ease-in-out,\r\n    width 0.25s ease-in-out;\r\n  container-type: inline-size;\r\n  @media (min-width: 1921px) {\r\n    min-width: 100%;\r\n  }\r\n  @media (max-width: 768px) {\r\n    position: unset;\r\n    container-type: unset;\r\n  }\r\n}\r\n\r\n.main {\r\n  overflow: visible;\r\n  @extend .grid, .pr-24, .transition-grid-template-columns, .gap-x-20;\r\n  grid-template-columns: 241px 1fr 335px;\r\n\r\n  @media (min-width: 1921px) {\r\n    grid-template-columns: 241px 1fr 395px;\r\n  }\r\n\r\n  @media (max-width: 768px) {\r\n    display: flex;\r\n    flex-direction: column-reverse;\r\n    padding-left: 10px;\r\n    padding-right: 10px;\r\n    position: unset;\r\n  }\r\n  &_menu_hide {\r\n    grid-template-columns: 102px 1fr 395px;\r\n\r\n    @media (max-width: 1785px) {\r\n      grid-template-columns: 102px 1fr 335px;\r\n    }\r\n  }\r\n}\r\n\r\n* {\r\n  box-sizing: border-box;\r\n}\r\n\r\np,\r\nul,\r\nol,\r\nli,\r\nspan,\r\na,\r\nsvg,\r\nh1,\r\nh2,\r\nh3,\r\nh4,\r\nh5,\r\nh6,\r\nhr,\r\nb,\r\nstrong,\r\nimg,\r\nblockquote,\r\nfigure {\r\n  @extend .m-0, .p-0;\r\n}\r\n\r\nbody {\r\n  @extend .text-text-main, .text-left, .bg-background-main;\r\n  font-family: var(--font-main);\r\n  font-feature-settings: normal;\r\n  font-variation-settings: normal;\r\n  text-underline-position: from-font;\r\n  text-decoration-skip-ink: none;\r\n}\r\n\r\np {\r\n  @extend .mt-0, .mb-0;\r\n}\r\n\r\nul {\r\n  @extend .p-0, .m-0;\r\n  list-style-type: none;\r\n}\r\n\r\n.loader {\r\n  position: fixed;\r\n  top: 0;\r\n  left: 0;\r\n  width: 100%;\r\n  height: 100%;\r\n  display: none;\r\n  z-index: 9999;\r\n  justify-content: center;\r\n  align-items: center;\r\n  flex-direction: column;\r\n  gap: 20px;\r\n  background: rgba(0, 0, 0, 0.5);\r\n  &.active {\r\n    display: flex;\r\n  }\r\n  &:after {\r\n    background: url(\"/images/icons/loader2.svg\");\r\n    height: 64px;\r\n    width: 64px;\r\n    content: \'\';\r\n    display: block;\r\n    position: absolute;\r\n    top: 10px;\r\n    right: 10px;\r\n  }\r\n}\r\n.modal_preloader {\r\n  position: absolute;\r\n  top: 0;\r\n  left: 0;\r\n  width: 100%;\r\n  height: 100%;\r\n  display: none;\r\n  z-index: 9;\r\n  justify-content: center;\r\n  align-items: center;\r\n  flex-direction: column;\r\n  gap: 20px;\r\n  background: rgba(0, 0, 0, 0.5);\r\n  border-radius: var(--block-radius);\r\n  &.active {\r\n    display: flex;\r\n  }\r\n}\r\n.blocked_text {\r\n  max-width: 100%;\r\n  margin: 0 auto;\r\n  background-color: var(--background-secondary);\r\n  border-radius: 16px;\r\n  padding: 20px 16px;\r\n  &_icon {\r\n    font-size: 94px;\r\n    line-height: 100px;\r\n    color: var(--primary-colors-secondary);\r\n    text-align: center;\r\n    display: block;\r\n  }\r\n  &_content {\r\n    margin-top: 40px;\r\n    font-size: 24px;\r\n    line-height: 28px;\r\n    color: var(--primary-colors-secondary);\r\n    text-align: center;\r\n    display: block;\r\n    max-width: 600px;\r\n  }\r\n}\r\n.mobile_hide {\r\n  @media (max-width: 768px) {\r\n    display: none;\r\n  }\r\n}\r\n.tablet_hide {\r\n  @media (min-width: 768px) and (max-width: 1024px) {\r\n    display: none;\r\n  }\r\n}\r\n.desktop_hide {\r\n  @media (min-width: 1024px) {\r\n    display: none;\r\n  }\r\n}\r\n\r\n.select {\r\n  @extend .h-48,\r\n  .min-h-48,\r\n  .max-h-48,\r\n  .border-solid,\r\n  .border-1,\r\n  .border-border-color-default,\r\n  .p1,\r\n  .bg-transparent,\r\n  .text-text-main,\r\n  .pl-20,\r\n  .pr-60,\r\n  .py-12,\r\n  .relative,\r\n  .transition-all;\r\n  border-radius: var(--card-radius);\r\n  outline: none;\r\n  -webkit-